(function(){const G = window.__game, V = G.Ven; const out = { i: 0 };
try {
  V.tick(); V.open(); out.on = V.on; if (!V.on) return JSON.stringify(out); const g = V.g, D = V.D; out.game = D.game;
  V.stake = D.stakes[2]; V.act({ act: 'play' }); out.ph = V.phase; for (let k = 0; k < 90; k++) g.update(V, 1 / 60);
  // win a stake match through the framework to test the trophy hook
  const m0 = G.save.money; V.finish(true, 'test', ['x'], V.stake * 2); out.phase2 = V.phase; out.trophy = !!G.save.col.prize['tr_' + D.game]; out.dm = G.save.money - m0;
  // souvenir
  V.lobby(); V.act({ act: 'souv' }); out.souv = !!G.save.ven.souv[D.game];
  // snack
  const h0 = 0; V.act({ act: 'snack' });
  V.close(); out.closed = !V.on;
} catch (e) { out.err = String(e && e.stack || e).slice(0, 400); }
G.Foot.exit();
return JSON.stringify(out);})()

